```jsx
function tentar(regra) {
  try {
    const novos = regra();
    setItens(novos);
  } catch (erro) {
    if (!(erro instanceof ErroDeNegocio)) throw erro;
    Alert.alert('Carrinho', erro.message);
  }
}
```

